dna = "ATGGCCTAAGGATGA"
stops = {"TAA", "TAG", "TGA"}
out = []
for f in range(3):
    n = 0
    for i in range(f, len(dna) - 2, 3):
        if dna[i:i+3] in stops:
            n += 1
    out.append(n)
print(*out)

table = {"AUG": "M", "GCU": "A", "GAA": "E", "UAA": "*"}
rna = "AUGGCUGAAUAA"
protein = ""
for i in range(0, len(rna) - 2, 3):
    aa = table[rna[i:i+3]]
    if aa == "*":
        break
    protein += aa
print(protein)

